comms.text:
@1 וְאַכְנֵשׁ משֶׁה יָת כָּל כְּנִשְׁתָּא דִבְנֵי יִשְרָאֵל וַאֲמַר לְהוֹן אִלֵין פִּתְגָמַיָא דִי פַקֵד יְיָ לְמֶעְבַּד יָתְהוֹן:
@2 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִדְתָּא וּבְיוֹמָא שְׁבִיעָאָה יְהֵי לְכוֹן קוּדְשָׁא שַׁבָּא שַׁבְּתָא קֳדָם יְיָ כָּל דְיַעֲבֵד בֵּה עִבִדְתָּא יִתְקְטֵל:
@3 לָא תְבַעֲרוּן אֶשָׁתָא בְּכֹל מוֹתְבָנֵיכוֹן בְּיוֹמָא דְשַׁבְּתָא:
@4 וַאֲמַר משֶׁה לְכָל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָּמָא דִי פַקֵד יְיָ לְמֵימָר:
@5 סָבוּ מִנְכוֹן אַפְרָשׁוּתָא קֳדָם יְיָ כֹּל דְיִתְרְעֵי לִבֵּהּ יַיְתֵי יָת אַפְרָשׁוּתָא קֳדָם יְיָ דַהֲבָא וְכַסְפָא וּנְחָשָׁא:
@6 וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי:
@7 וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי דְסַסְגוֹנָא וְאָעֵי שִׁטִין:
@8 וּמִשְׁחָא לְאַנְהָרוּתָא וּבוּסְמַיָא לִמְשַׁח רְבוּתָא וְלִקְטֹרֶת בּוּסְמַיָא:
@9 וְאַבְנֵי בוּרְלָא וְאַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְּאֵפוֹדָא וּבְחוּשְׁנָא:
@10 וְכָל חַכִּימֵי לִבָּא בְּכוֹן יֵיתוּן וְיַעְבְדוּן יָת כָּל דִי פַקֵד יְיָ:
@11 יָת מַשְׁכְּנָא יָת פְּרָסֵהּ וְיָת חוֹפָאֵהּ יָת פּוּרְפוֹהִי וְיָת דַפּוֹהִי יָת עַבְרוֹהִי יָת עַמוּדוֹהִי וְיָת סַמְכוֹהִי:
@12 יָת אֲרוֹנָא וְיָת אֲרִיחוֹהִי יָת כַּפֻּרְתָּא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@13 יָת פָּתוֹרָא וְיָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@14 וְיָת מְנַרְתָּא דְאַנְהוֹרֵי וְיָת מָנָהָא וְיָת בּוֹצִינָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@15 וְיָת מַדְבְּחָא דִקְטוֹרֶת בּוּסְמַיָא וְיָת אֲרִיחוֹהִי וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דְתַרְעָא לִתְרַע מַשְׁכְּנָא:
@16 יָת מַדְבְּחָא דַעֲלָתָא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אָרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@17 יָת סְרָדֵי דַרְתָּא יָת עַמוּדוֹהִי וְיָת סַמְכָהָא וְיָת פְּרָסָא דִתְרַע דַרְתָּא:
@18 יָת סִכֵּי מַשְׁכְּנָא וְיָת סִכֵּי דְדַרְתָּא וְיָת אַטוּנֵיהוֹן:
@19 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@20 וּנְפָקוּ כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל מִן קֳדָם משֶׁה:
@21 וַאֲתוֹ כָּל גְבַר דְאִתְרְעֵי לִבֵּהּ וְכֹל דִי אַשְׁלֵמַת רוּחֵהּ יָתֵהּ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ לַעֲבִידַת מַשְׁכַּן זִמְנָא וּלְכָל פֻּלְחָנֵהּ וְלִלְבוּשֵׁי קוּדְשָׁא:
@22 וּמַיְתַן גֻבְרַיָא עַל נְשַׁיָא כֹּל דְאִתְרְעֵי לִבֵּהּ אַיְתִיאוּ שֵׁירִין וְשִׁבְכִין וְעִזְקַן וּמָחוּךְ כָּל מָן דִדְהַב וְכָל גְּבַר דִי אֲרֵים אֲרָמוּת דַהֲבָא קֳדָם יְיָ:
@23 וְכָל גְבַר דְאִשְׁתְּכַח עִמֵהּ תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ וּמֵעַזֵי וּמַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וּמַשְׁכֵי סַסְגוֹנָא אַיְתִיאוּ:
@24 כָּל דַאֲרֵים אֲרָמוּת כְּסַף וּנְחַשׁ אַיְתִיאוּ יָת אַפְרָשׁוּתָא קֳדָם יְיָ וְכֹל דִי אִשְׁתְּכַח עִמֵהּ אָעֵי שִׁטִין לְכָל עִבִידַת פֻּלְחָנָא אַיְתִיאוּ:
@25 וְכָל אִתְּתָא חַכִּימַת לִבָּא בִּידָהָא מְעַזְלָא וּמַיְתַן כַּד עָזֵל יָת תִּכְלָא וְיָת אַרְגְוָנָא יָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@26 וְכָל נְשַׁיָא דְאִתְרְעֵי לִבְּהֶן עִמְהֶן בְּחָכְמָא עַזְלַן יָת מֵעַזְיָא:
@27 וְרַבְרְבַיָא אַיְתִיאוּ יָת אַבְנֵי בוּרְלָא וְיָת אַבְנֵי אַשְׁלָמוּתָא לְשַׁקָעָא בְאֵפוֹדָא וּבְחוּשְׁנָא:
@28 וְיָת בּוּסְמָא וְיָת מִשְׁחָא לְאַנְהָרוּתָא וּלְמִשְׁחָא דִרְבוּתָא וְלִקְטוֹרֶת בּוּסְמַיָא:
@29 כָּל גְבַר וְאִתְּתָא דְאִתְרְעֵי לִבְּהוֹן עִמְהוֹן לְאַיְתָאָה לְכָל עִבִדְתָּא דִי פַקֵד יְיָ לְמֶעְבַּד בִּידָא דְמשֶׁה אַיְתִיאוּ בְנֵי יִשְׂרָאֵל נְדַבְתָּא קֳדָם יְיָ:
@30 וַאֲמַר משֶׁה לִבְנֵי יִשְׂרָאֵל חֲזוֹ דְרַבִּי יְיָ בְּשׁוּם בְּצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה:
@31 וְאַשְׁלֵם עִמֵהּ רוּחַ נְבוּאָה מִן קֳדָם יְיָ בְּחָכְמְתָא בְּסוּכְלְתָנוּ וּבְמַדַע וּבְכָל עִבִידָא:
@32 וּלְאַלָפָא אוּמַנְוָן לְמֶעְבַּד בְּדַהֲבָא וּבְכַסְפָא וּבִנְחָשָׁא:
@33 וּבְאוּמָנוּת אֶבֶן טָבָא לְאַשְׁלָמָא וּבְנַגָרוּת אָעָא לְמֶעְבַּד בְּכָל עִבִידַת אוּמַנְוָן:
@34 וּלְאַלָפָא יְהַב בְּלִבֵּהּ הוּא וְאָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן:
@35 אַשְׁלֵם עִמְהוֹן חַכִּימוּת לִבָּא לְמֶעְבַּד כָּל עִבִידַת נַגָר וְאָמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא בִּצְבַע זְהוֹרִי וּבְבוּצָא וּמַחֵי עָבְדֵי כָּל עֲבִידָא וּמַלְפֵי אוּמַנְוָן:
@36 וַעֲבַד בְּצַלְאֵל וְאָהֳלִיאָב וְכָל גְבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמָא וְסוּכְלְתָנוּתָא בְּהוֹן לְמִדַע לְמֶעְבַּד יָת כָּל עִבִידַת פָלְחַן קוּדְשָׁא לְכֹל דִי פַקֵד יְיָ:
@37 וּקְרָא משֶׁה לִבְצַלְאֵל וּלְאָהֳלִיאָב וּלְכָל גְּבַר חַכִּים לִבָּא דִיהַב יְיָ חָכְמְתָא בְּלִבֵּה כָּל דְאִתְרְעֵי לִבֵּהּ לְמִקְרַב לְעִבִדְתָּא לְמֶעְבַּד יָתַהּ:
@38 וּנְסִיבוּ מִן קֳדָם משֶׁה יָת כָּל אַפְרָשׁוּתָא דִי אַיְתִיאוּ בְּנֵי יִשְׂרָאֵל לְעִבִידַת פָּלְחַן קוּדְשָׁא לְמֶעְבַּד יָתַהּ וְאִנוּן מַיְתַן לֵהּ עוֹד נְדַבְתָּא בִּצְפַר בִּצְפָר:
@39 וַאֲתוֹ כָּל חַכִּימַיָא דְעָבְדִין יָת כָּל עִבִידַת קוּדְשָׁא גְבַר גְבַר מֵעִבִדְתֵּהּ דְאִנוּן עָבְדִין:
@40 וַאֲמָרוּ לְמשֶׁה לְמֵימַר מַסְגַן עַמָא לְאַיְתָאָה מִסַת פָּלְחָנָא לְעִבִדְתָּא דְפַקֵד יְיָ לְמֶעְבַּד יָתַהּ:
@41 וּפַקֵד משֶׁה וַאַעֲבַרוּ כְרוֹזָא בְּמַשְׁרִיתָא לְמֵימַר גְבַר וְאִתְּתָא לָא יַעַבְדוּן עוֹד עִבִדְתָּא לְאַפְרָשׁוּת קוּדְשָׁא וּפְסַק עַמָא מִלְאַיְתָאָה:
@42 וְעִבִדְתָּא הֲוַת מִסַת לְכָל עִבִדְתָּא לְמֶעְבַּד יָתַהּ וִיתָרָת:
@43 וַעֲבָדוּ כָל חַכִּימֵי לִבָּא בְּעָבְדֵי עִבִדְתָּא יָת מַשְׁכְּנָא עֲשַׂר יְרִיעָן דְבוּץ שְׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי צוּרַת כְּרוּבִין עוֹבַד אֳמָן עֲבַד יָתְהוֹן:
@44 אֻרְכָּא דִירִעֲתָא חֲדָא עַסְרִין וּתְמַנְיָא אַמִין וּפוּתְיָא אַרְבַּע אַמִין דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְכָל יְרִיעָתָא:
@45 וְלָפֵף יָת חָמֵשׁ יְרִיעָן חֲדָא עִם חֲדָא וְחָמֵשׁ יְרִיעָן לָפֵף חֲדָא עִם חֲדָא:
@46 וַעֲבַד עֲנוּבִין דְתִכְלָא עַל סִפְתָא דִירִעֲתָא חֲדָא מִסִטְרָא בֵּית לוֹפֵי כֵּן עֲבַד בְּסִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי תִּנְיֵתָא:
@47 חַמְשִׁין עֲנוּבִין עֲבַד בִּירִיעֲתָא חֲדָא וְחַמְשִׁין עֲנוּבִין עֲבַד בְּסִטְרָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא מְכַוְנָן עֲנוּבַיָא חֲדָא לָקֳבֵל חֲדָא:
@48 וַעֲבַד חַמְשִׁין פּוּרְפִין דִדְהַב וְלָפֵף יָת יְרִיעֲתָא חֲדָא עִם חֲדָא בְּפוּרְפַיָא וַהֲוָה מַשְׁכְּנָא חָד:
@49 וַעֲבַד יְרִיעָן דִמְעַזֵי לִפְרָסָא עַל מַשְׁכְּנָא חַד עֲשַׂר יְרִיעָן עֲבַד יָתְהֶן:
@50 אֻרְכָּא דִירִיעֲתָא חֲדָא תְּלָתִין בְּאַמִין וְאַרְבַּע אַמִין פּוּתְיָא דִירִיעֲתָא חֲדָא מְשַׁחְתָּא חֲדָא לְחַד עֲשַׂר יְרִיעָן:
@51 וְלָפֵף יָת חָמֵשׁ יְרִיעָן לְחוֹד וְיָת שִׁית יְרִיעָן לְחוֹד:
@52 וַעֲבַד עֲנוּבִין חַמְשִׁין עַל סִפְתָא דִירִיעֲתָא בְּסִטְרָא בֵּית לוֹפֵי וְחַמְשִׁין עֲנוּבִין עֲבַד עַל סִפְתָא דִירִיעֲתָא דְבֵית לוֹפֵי תִּנְיֵתָא:
@53 וַעֲבַד פּוּרְפִין דִנְחָשָׁא חַמְשִׁין לְלַפָּפָא יָת מַשְׁכְּנָא לְמֶהֱוֵי חָד:
@54 וַעֲבַד חוֹפָאָה לְמַשְׁכְּנָא מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְחוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא מִלְעֵלָא:
@55 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא דְאָעֵי שִׁטִין קָיְמִין:
@56 עֲשַׂר אַמִין אֻרְכָּא דְדַפָּא וְאַמְתָא וּפַלְגוּת אַמְתָא פּוּתְיָא דְדַפָּא חָד:
@57 תַּרְתֵּין צִירִין לְדַפָּא חַד מְשַׁלְבִין חֲדָא לָקֳבֵל חֲדָא כֵּן עֲבַד לְכֹל דַפֵּי מַשְׁכְּנָא:
@58 וַעֲבַד יָת דַפַּיָא לְמַשְׁכְּנָא עֶסְרִין דַפִּין לְרוּחַ עֵבַר דָרוֹמָא:
@59 וְאַרְבְּעִין סַמְכִין דִכְסַף עֲבַד תְּחוֹת עֶסְרִין דַפִּין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חַד לִתְרֵין צִירוֹהִי:
@60 וְלִסְטַר מַשְׁכְּנָא תִּנְיֵתָא לְרוּחַ צִפּוּנָא עֲבַד עֶסְרִין דַפִּין:
@61 וְאַרְבְּעִין סַמְכֵיהוֹן דִכְסָף תְּרֵין סַמְכִין תְּחוֹת דַפָּא חַד וּתְרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@62 וְלִסְיָפֵי מַשְׁכְּנָא מַעַרְבָא עֲבַד שִׁתָּא דַפִין:
@63 וּתְרֵין דַפִין עֲבַד לְזָוְיַת מַשְׁכְּנָא בְּסוֹפֵיהוֹן:
@64 וַהֲווֹ מְכַוְנִין מִלְרַע וְכַחֲדָא הֲווֹ מְכַוְנִין עַל רֵישֵׁהּ לְעִזְקָתָא חֲדָא כֵּן עֲבַד לְתַרְוֵיהוֹן לִתְרֵין זָוְיָן:
@65 וַהֲווֹ תְּמַנְיָא דַפִּין וְסַמְכֵיהוֹן דִכְסַף שִׁתָּא עֲשַׂר סַמְכִין תְּרֵין סַמְכִין תְּרֵין סַמְכִין תְּחוֹת דַפָּא חָד:
@66 וַעֲבַד עַבְּרֵי דְאָעֵי שִׁטִין חַמְשָׁא לְדַפֵּי סְטַר מַשְׁכְּנָא חָד:
@67 וְחַמְשָׁא עַבְּרִין לְדַפֵּי סְטַר מַשְׁכְּנָא תִּנְיֵתָא וְחַמְשָׁא עַבְּרִין לְדַפֵּי מַשְׁכְּנָא לְסוֹפֵיהוֹן מַעַרְבָא:
@68 וַעֲבַד יָת עַבְּרָא מְצִיעָאָה לְאַעְבָּרָא בְּגוֹ דַפַּיָא מִן סְיָפֵי לִסְיָפֵי:
@69 וְיָת דַפַּיָא חֲפָא דַהֲבָא וְיָת עִזְקָתְהוֹן עֲבַד דַהֲבָא אַתְרָא לְעַבְּרַיָא וַחֲפָא יָת עַבְּרַיָא דַהֲבָא:
@70 וַעֲבַד יָת פָּרֻכְתָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן עֲבַד יָתַהּ צוּרַת כְּרוּבִין:
@71 וַעֲבַד לַהּ אַרְבְּעָא עַמוּדֵי שִׁטִין וַחֲפָנוּן דַהֲבָא וָוֵיהוֹן דַהֲבָא וְאַתִּיךְ לְהוֹן אַרְבְּעָא סַמְכִין דִכְסָף:
@72 וַעֲבַד פְּרָסָא לִתְרַע מַשְׁכְּנָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד צַיָר:
@73 וְיָת עַמוּדוֹהִי חַמְשָׁא וְיָת וָוֵיהוֹן וַחֲפָא רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דַהֲבָא וְסַמְכֵיהוֹן חַמְשָׁא נְחָשָׁא:
@74 וַעֲבַד בְּצַלְאֵל יָת אֲרוֹנָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכֵּהּ וְאַמְתָא וּפַלְגָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@75 וַחֲפָהִי דְהַב דְכֵי מִגָּו וּמִבָּרָא וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@76 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהַב עַל אַרְבַּע זִוְיָתֵהּ וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ חַד וְתַרְתֵּין עִזְקַן עַל סִטְרֵהּ תִּנְיֵתָא:
@77 וַעֲבַד אֲרִיחֵי דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@78 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי אֲרוֹנָא לְמִטָל יָת אֲרוֹנָא:
@79 וַעֲבַד כַּפֻּרְתָּא דְהַב דְכֵי תַּרְתֵּין אַמִין וּפַלְגָא אֻרְכַּהּ וְאַמְתָא וּפַלְגָא פְתָיַהּ:
@80 וַעֲבַד תְּרֵין כְּרוּבִין דִדְהָב נְגִיד עֲבַד יָתְהוֹן מִתְּרֵין סִטְרֵי כַפֻּרְתָּא:
@81 כְּרוּבָא חַד מִסִטְרָא מִכָּא וּכְרוּבָא חַד מִסִטְרָא מִכָּא מִן כַּפֻּרְתָּא עֲבַד יָת כְּרוּבַיָא מִתְּרֵין סִטְרוֹהִי:
@82 וַהֲווֹ כְרוּבַיָא פְּרִיסָן גַדְפֵיהוֹן לְעֵלָא נָטְלִין בְּגַדְפֵיהוֹן עַל כַּפֻּרְתָּא וְאַפֵּיהוֹן חַד לָקֳבֵל חַד לָקֳבֵל כַּפֻּרְתָּא הֲווֹ אַפֵּי כְרוּבַיָא:
@83 וַעֲבַד יָת פָּתוֹרָא דְאָעֵי שִׁטִין תַּרְתֵּין אַמִין אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ וְאַמְתָא וּפַלְגָא רוּמֵהּ:
@84 וַחֲפָא יָתֵהּ דְהַב דְכֵי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@85 וַעֲבַד לֵהּ גְדַנְפָא רוּמֵהּ פּוּשְׁכָא סְחוֹר סְחוֹר וַעֲבַד דֵיר דִדְהַב לִגְדַנְפֵהּ סְחוֹר סְחוֹר:
@86 וְאַתִּיךְ לֵהּ אַרְבַּע עִזְקַן דִדְהָב וִיהַב יָת עִזְקֳתָא עַל אַרְבַּע זִוְיָתָא דִי לְאַרְבַּע רַגְלוֹהִי:
@87 לָקֳבֵל גְדַנְפָא הֲווֹ עִזְקָתָא אַתְרָא לַאֲרִיחַיָא לְמִטַל יָת פָּתוֹרָא:
@88 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִּין וַחֲפָא יָתְהוֹן דַהֲבָא לְמִטַל יָת פָּתוֹרָא:
@89 וַעֲבַד יָת מָנַיָא דִי עַל פָּתוֹרָא יָת מָגִיסוֹהִי וְיָת בָּזִיכּוֹהִי וְיָת מְכִילָתֵהּ וְיָת קַשְׂוָתָא דִי יִתְנַסַךְ בְּהוֹן דְהַב דְכֵי:
@90 וַעֲבַד יָת מְנַרְתָּא דְהַב דְכֵי נְגִיד עֲבַד יָת מְנַרְתָּא שִׁידַהּ וּקְנַהּ כַּלִידָהָא חֵזוּרָהָא וְשׁוֹשַׁנָהָא מִנַהּ הֲווֹ:
@91 וְשִׁתָּא קְנִין נָפְקִין מִסִטְרָהָא תְּלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ חַד וּתְלָתָא קְנֵי מְנַרְתָּא מִסִטְרַהּ תִּנְיָנָא:
@92 תְּלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן וּתְלָתָא כַלִידִין מְצַיְרִין בְּקַנְיָא חַד חֵזוּר וְשׁוֹשָׁן כֵּן לְשִׁתָּא קְנִין דְנָפְקִין מִן מְנַרְתָּא:
@93 וּבִמְנַרְתָּא אַרְבְּעָא כַלִידִין מְצַיְרִין חֵזוּרָהָא וְשׁוֹשַׁנָהָא:
@94 וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ וְחֵזוּר תְּחוֹת תְּרֵין קְנִין מִנַהּ לְשִׁתָּא קְנִין דְנַפְקִין מִנַהּ:
@95 חֵזוּרֵיהוֹן וּקְנֵיהוֹן מִנַהּ הֲווֹ כֻּלַהּ נְגִידָא חֲדָא דְהַב דְכֵי:
@96 וַעֲבַד יָת בּוֹצִינָהָא שִׁבְעָא וְצִבְיְתָהָא וּמַחְתְּיָתָהָא דְהַב דְכֵי:
@97 כִּכְּרָא דְהַב דְכֵי עֲבַד יָתַהּ וְיָת כָּל מָנָהָא:
@98 וַעֲבַד יָת מַדְבְּחָא דִקְטֹּרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי:
@99 וַחֲפָא יָתֵהּ דְהַב דְכֵי יָת אִגָרֵה וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וַעֲבַד לֵהּ דֵיר דִדְהַב סְחוֹר סְחוֹר:
@100 וְתַרְתֵּין עִזְקַן דִדְהַב עֲבַד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ עַל תְּרֵין סִטְרוֹהִי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@101 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן דַהֲבָא:
@102 וַעֲבַד יָת מִשְׁחָא דִרְבוּתָא קוּדְשָׁא וְיָת קְטֹרֶת בּוּסְמַיָא דְכֵי עוֹבַד בּוּסְמָנוּ:
@103 וַעֲבַד יָת מַדְבְּחָא דַעֲלָתָא דְאָעֵי שִׁטִין חֲמֵשׁ אַמִין אֻרְכֵּהּ וַחֲמֵשׁ אַמִין פְּתָיֵהּ מְרַבַּע וּתְלָתָא אַמִין רוּמֵהּ:
@104 וַעֲבַד קַרְנוֹהִי עַל אַרְבַּע זִוְיָתֵהּ מִנֵהּ הֲווֹ קַרְנוֹהִי וַחֲפָא יָתֵהּ נְחָשָׁא:
@105 וַעֲבַד יָת כָּל מָנֵי מַדְבְּחָא יָת פְּסַכְתְּרָוָתָא וְיָת מַגְרוֹפְיָתָא וְיָת מִזְרְקָתָא יָת צִנוֹרְיָתָא וְיָת מַחְתְּיָתָא כָּל מָנוֹהִי עֲבַד נְחָשָׁא:
@106 וַעֲבַד לְּמַדְבְּחָא סְרָדָא עוֹבַד מְצַדְתָּא דִנְחָשָׁא תְּחוֹת סוֹבָבֵהּ מִלְרַע עַד פַּלְגֵהּ:
@107 וְאַתִּיךְ אַרְבַּע עִזְקָתָא בְּאַרְבַּע סִטְרָתָא לִסְרָדָא דִנְחָשָׁא אַתְרָא לַאֲרִיחַיָא:
@108 וַעֲבַד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וַחֲפָא יָתְהוֹן נְחָשָׁא:
@109 וְאָעֵיל יָת אֲרִיחַיָא בְּעִזְקָתָא עַל סִטְרֵי מַדְבְּחָא לְמִטַל יָתֵהּ בְּהוֹן חֲלִיל לוּחִין עֲבַד יָתֵהּ:
@110 וַעֲבַד יָת כִּיוֹרָא נְחָשָׁא וְיָת בְּסִיסֵהּ נְחָשָׁא בְּמֶחְזְיַן נְשַׁיָא דְאָתְיָן לְצַלָאָה בִּתְרַע מַשְׁכַּן זִמְנָא:
@111 וַעֲבַד יָת דַרְתָּא לְרוּחַ עֵבַר דָרוֹמָא סְרָדֵי דַרְתָּא דְבוּץ שְׁזִיר מְאָה בְאַמִין:
@112 עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@113 וּלְרוּחַ צִפּוּנָא מְאָה אַמִין עַמוּדֵיהוֹן עֶסְרִין וְסַמְכֵיהוֹן עֶסְרִין נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@114 וּלְרוּחַ מַעַרְבָא סְרָדִין חַמְשִׁין בְּאַמִין עֲמוּדֵיהוֹן עַסְרָא וְסַמְכֵיהוֹן עַסְרָא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסָף:
@115 וּלְרוּחַ קִדוּמָא מָדִינְחָא חַמְשִׁין אַמִין:
@116 סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין לְעִבְרָא עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@117 וּלְעִבְרָא תִנְיֵתָא מִכָּא וּמִכָּא לִתְרַע דַרְתָּא סְרָדִין חֲמֵשׁ עֶסְרֵי אַמִין עַמוּדֵיהוֹן תְּלָתָא וְסַמְכֵיהוֹן תְּלָתָא:
@118 כָּל סְרָדֵי דְדַרְתָּא סְחוֹר סְחוֹר דְבוּץ שְׁזִיר:
@119 וְסַמְכַיָא לְעַמוּדַיָא נְחָשָׁא וָוֵי עַמוּדַיָא וְכִבּוּשֵׁיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן דִכְסָף וְאִנוּן מְכַבְּשִׁין דִכְסָף כָּל עַמוּדֵי דַרְתָּא:
@120 וּפְרָסָא דִתְרַע דַרְתָּא עוֹבַד צַיָר תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר וְעֶסְרִין אַמִין אֻרְכָּא וְרוּמָא בְּפוּתְיָא חֲמֵשׁ אַמִין לָקֳבֵל סְרָדֵי דַרְתָּא:
@121 וְעַמוּדֵיהוֹן אַרְבְּעָא וְסַמְכֵיהוֹן אַרְבְּעָא נְחָשָׁא וָוֵיהוֹן דִכְסַף וְחִפּוּי רֵישֵׁיהוֹן וְכִבּוּשֵׁיהוֹן דִכְסָף:
@122 וְכָל סִכַּיָא לְמַשְׁכְּנָא וּלְדַרְתָּא סְחוֹר סְחוֹר דִנְחָשָׁא: ססס:

@1 **ויקהל משה.** למחרת יום הכפורים כשירד מן ההר, והוא לשון הפעיל, שאינו אוסף אנשים בידים, אלא הן נאספים על פי דבורו, ותרגומו ואכנש:
@2 **ששת ימים.** הקדים להם אזהרת שבת לצווי מלאכת המשכן, לומר שאינה דוחה את השבת:
@3 **לא תבערו אש.** יש מרבותינו אומרים הבערה ללאו יצאת, ויש אומרים לחלק יצאת:
@4 **זה הדבר אשר צוה ה'.** לי לאמר לכם:
@5 **נדיב לבו.** על שם שלבו נדבו קרוי נדיב לב. כבר פרשתי נדבת המשכן ומלאכתו במקום צואתן:
@11 **את המשכן.** יריעות התחתונות הנראות בתוכו קרויים משכן: **את אהלו.** הוא אהל יריעות עזים העשוי לגג: **ואת מכסהו.** מכסה עורות האילים והתחשים:
@12 **ואת פרכת המסך.** פרוכת המחצה. כל דבר המגין, בין מלמעלה בין מכנגד, קרוי מסך וסכך, וכן (איוב א י) שכת בעדו, (הושע ב ח) הנני שך את דרכך:
@13 **לחם הפנים.** כבר פרשתי (שמות כה כח) על שם שהיו לו פנים לכאן ולכאן, שהוא עשוי כמין תבה פרוצה:
@14 **ואת כליה.** מלקחים ומחתות: **נרתיה.** לוציי''ש בלעז בזכים שהשמן והפתילות נתונין בהן: **ואת שמן המאור.** אף הוא צריך חכמי לב, שהוא משנה משאר שמנים, כמו שמפורש במנחות (דף פו א) מגרגרו בראש הזית, והוא כתית וזך:
@15 **מסך הפתח.** וילון שלפני המזרח שלא היו שם לא קרשים ולא יריעות:
@17 **את עמודיו ואת אדניה.** הרי חצר קרוי כאן לשון זכר ולשון נקבה, וכן דברים הרבה: **ואת מסך שער החצר.** וילון פרוש לצד המזרח עשרים אמה אמצעיות של רוחב החצר, שהיה חמשים רחב, וסתומין המנו לצד צפון חמש עשרה אמה וכן לדרום, שנאמר (שמות כז יד) וחמש עשרה אמה קלעים לכתף:
@18 **יתדת.** לתקוע ולקשור בהם סופי היריעות בארץ שלא ינועו ברוח: **מיתריהם.** חבלים לקשור:
@19 **בגדי השרד.** לכסות הארון והשלחן, והמנורה והמזבחות בשעת סלוק מסעות:
@22 **על הנשים.** עם הנשים וסמוכין אליהם: **חח.** הוא תכשיט של זהב עגול נתון על הזרוע, והוא הצמיד: **וכומז.** כלי זהב הוא נתון כנגד אותו מקום לאשה. ורבותינו פרשו שם כומז כאן מקום זמה:
@23 **וכל איש אשר נמצא אתו.** תכלת או ארגמן או תולעת שני או עורות אילים או תחשים כלם הביאו:
@26 **טוו את העזים.** היא היתה אמנות יתרה, שמעל גבי העזים טווין אותן:
@27 **והנשאם הביאו.** אמר ר' נתן מה ראו נשיאים להתנדב בחנכת המזבח בתחלה, ובמלאכת המשכן לא התנדבו בתחלה, אלא כך אמרו נשיאים יתנדבו צבור מה שמתנדבין, ומה שמחסירים אנו משלימין אותו. כיון שהשלימו צבור את הכל, שנאמר (שמות לו ז) והמלאכה היתה דים, אמרו נשיאים מה עלינו לעשות, הביאו את אבני השהם וגו' , לכך התנדבו בחנכת המזבח תחלה. ולפי שנתעצלו מתחלה נחסרה אות משמם והנשאם כתיב:
@30 **חור.** בנה של מרים היה:
@34 **ואהליאב.** משבט דן, מן הירודין שבשבטים מבני השפחות, והשוהו המקום לבצלאל למלאכת המשכן, והוא מגדולי השבטים, לקים מה שנאמר (איוב לד יט) ולא נכר שוע לפני דל:
@40 **מדי העבדה.** יותר מכדי צורך העבודה:
@41 **ויכלא.** לשון מניעה:
@42 **והמלאכה היתה דים לכל המלאכה.** ומלאכת ההבאה היתה דים של עושי המשכן. **לכל המלאכה.** של משכן **לעשות אותה.** ולהותיר: **והותר.** כמו (שמות ח יא) והכבד את לבו, (מלכים ב' ג כד) והכות את מואב:
@74 **ויעש בצלאל.** לפי שנתן נפשו על המלאכה יותר משאר חכמים, נקראת על שמו:
@109 **נבוב לחת.** נבוב הוא חלול, וכן (ירמיה נב, כא) ועביו ארבע אצבעות נבוב: **נבוב לחת.** הלוחות של עצי שטים לכל רוח והחלל באמצע:
@110 **במראת הצובאת.** בנות ישראל היו בידן מראות, שרואות בהן כשהן מתקשטות, ואף אותן לא עכבו מלהביא לנדבת המשכן, והיה מואס משה בהן, מפני שעשויים ליצר הרע, אמר לו הקדוש ברוך הוא קבל, כי אלו חביבין עלי מן הכל, שעל ידיהם העמידו הנשים צבאות רבות במצרים. כשהיו בעליהם יגעים בעבודת פרך, היו הולכות ומוליכות להם מאכל ומשתה ומאכילות אותם ונוטלות המראות, וכל אחת רואה עצמה עם בעלה במראה ומשדלתו בדברים, לומר אני נאה ממך, ומתוך כך מביאות לבעליהן לידי תאוה ונזקקות להם, ומתעברות ויולדות שם, שנאמר (שיר השירים ח ה) תחת התפוח עוררתיך, וזהו שנאמר במראות הצובאות. ונעשה הכיור מהם, שהוא לשום שלום בין איש לאשתו, להשקות ממים שבתוכו את שקנא לה בעלה ונסתרה, ותדע לך, שהן מראות ממש, שהרי נאמר (שמות לח כט ל) , ונחשת התנופה שבעים ככר וגו' , ויעש בה וגו' , וכיור וכנו לא הזכרו שם, למדת שלא היה נחשת של כיור מנחשת התנופה, כך דרש רבי תנחומא, וכן תרגם אנקלוס במחזית נשיא, והוא תרגום של מראות מירידויר''ש בלעז . וכן מצינו בישעיה (ישעיה ג כג) והגליונים, מתרגמנן ומחזיתא: **אשר צבאו.** להביא נדבתן:
@120 **לעמת קלעי החצר.** כמדת קלעי החצר:

@1 **ויקהל משה את כל עדת בני ישראל** . יכלול ''כל עדת בני ישראל'' האנשים והנשים, כי כלם התנדבו במלאכת המשכן. והנה משה אחר שצוה לאהרן והנשיאים וכל בני ישראל האנשים כל אשר דבר ה' אתו בהר סיני אחרי שבור הלוחות (לעיל לד לב), ונתן על פניו המסוה (שם פסוק לג), חזר וצוה והקהילו אליו כל העדה אנשים ונשים. ויתכן שהיה זה ביום מחרת רדתו. ואמר לכולם ענין המשכן אשר נצטוה בו מתחלה קודם שבור הלוחות, כי כיון שנתרצה להם הקב''ה ונתן לו הלוחות שניות וכרת עמו ברית חדשה שילך השם בקרבם, הנה חזרו לקדמותם ולאהבת כלולותם, ובידוע שתהיה שכינתו בתוכם כענין שצוהו תחלה, כמו שאמר (לעיל כה ח) ועשו לי מקדש ושכנתי בתוכם, ולכן צוה אותם משה עתה בכל מה שנצטוה מתחלה:
@1 (א~ב) **אלה הדברים אשר צוה ה' לעשות אותם ששת ימים תעשה מלאכה** . אמר **אלה הדברים אשר צוה ה' לעשות** על מלאכת המשכן וכל כליו וכל עבודתו. והקדים השבת לאמר כי ששת ימים תעשה מלאכת אלה הדברים ולא ביום השביעי שהוא קדש לה'. ומכאן שאין מלאכת המשכן דוחה שבת, ולא ממדרש אך, כמו שפרשתי בסדר כי תשא (לעיל לא יג):
@3 **לא תבערו אש בכל מושבותיכם ביום השבת** . ענין הכתוב הזה ודאי לאסור בשבת גם מלאכת אוכל נפש, כי אמר כל **העושה בו מלאכה יומת** , ופירש שלא יבערו גם אש לאפות לחם ולבשל בשר כי האש צורך כל מאכל. והוצרך לומר כן מפני שלא אמר ''העושה בו כל מלאכה'' כאשר אמר בעשרת הדברות (לעיל כ י) לא תעשה כל מלאכה, ואמר מלאכה סתם, והיה אפשר שנוציא מן הכלל מלאכת אוכל נפש, כי כן נאמר בחג המצות (דברים טז ח) לא תעשה מלאכה ואין אוכל נפש בכללו, ולכך הזכיר בפירוש שאף אוכל נפש אסור בו:
@3 **וכלשון** הזה מצאתי במדרש (מכילתא כאן) רבי נתן אומר **לא תבערו אש בכל מושבותיכם ביום השבת** למה נאמר, לפי שהוא אומר **ויקהל משה את כל עדת בני ישראל** , שומע אני יהא רשאי להדליק לו את הנר, להטמין לו את החמין, ולעשות לו מדורה בשבת, ת''ל **לא תבערו אש בכל מושבותיכם ביום השבת** . וזה קרוב למה שאמרנו, שלא היו מלאכות הללו שהן הנאה לגופו בכלל איסור הראשון. ורצה רבי נתן לומר שלא הוצרך הכתוב לאסור אפייה ובשול ושאר צרכי אוכל נפש, שכבר אמר להם את אשר תאפו אפו ואת אשר תבשלו בשלו (לעיל טז כג), אבל עדיין כל מלאכות שאדם נהנה בהן ואינן עושין אלא הנאה לגוף כגון הדלקת הנר ומדורה ורחיצת גופו בחמין יהיו מותרות כי זה מעונג שבת, לכך נאמר **לא תבערו אש** לאסור הכל:
@3 **ולרבותינו** עוד בו מדרש בתלמוד (שבת ע.) מפני שלא אמר כל העושה בו כל מלאכה יומת, או שיאמר כל המבעיר אש בכל מושבותיכם יומת, אמרו שיצאת להקל בה להיותה בלאו. ויש אומר שיצאה לחלק, לפי שהיתה בכלל לא תעשה כל מלאכה (לעיל כ י):
@5 **יביאה את תרומת ה'** . כמו יביא את תרומת ה', אבל יכנה ויפרש. וכן ותפתח ותראהו את הילד (לעיל ב ו), בבואו האיש (יחזקאל י ג), אשר לא יעבדו אותו את נבוכדנצר (ירמיה כז ח), אשר אנכי נותן להם לבני ישראל (יהושע א ב), ורבים כן:
@5 **ועל** דרך האמת הוא כמו יביאה עם תרומת ה' (זהר ויקהל קצח:), שיביא התרומה העליונה, בסוד ויקחו לי תרומה (לעיל כה ב). וכבר פרשתיו (לעיל כה ג). ולרבותינו מדרש ב''ותפתח ותראהו את הילד'' (לעיל ב ו), שראתה עמו שכינה (סוטה יב:):
@11 והנה משה הוצרך לספר לכל העדה כל המלאכה שצוה אותו השם, כדי להודיע להם שצריכין להביא נדבה רבה, כי המלאכה גדולה, ולכך ספר להם **המשכן את אהלו ואת מכסהו וגו'** כולן הזכירן על דרך הכלל. וטעם **את המשכן** , **את הארון** , **את השלחן** , וכל הנזכרים, בה''א הידיעה, כאומר **את המשכן** ואת הכלים אשר נגיד לחכמים העושים במלאכה בפרטן ובשעורן, כי עתה לכל העדה לא יגידם אלא בשמותם בכלל:
@21 **ויבאו כל איש אשר נשאו לבו** . על החכמים העושים במלאכה יאמר כן, כי לא מצינו על המתנדבים נשיאות לב, אבל יזכיר בהם נדיבות, וטעם **אשר נשאו לבו** , לקרבה אל המלאכה, כי לא היה בהם שלמד את המלאכות האלה ממלמד, או מי שאימן בהן ידיו כלל, אבל מצא בטבעו שידע לעשות כן, ויגבה לבו בדרכי ה' (דה''ב יז ו) לבא לפני משה לאמר לו אני אעשה כל אשר אדני דובר. וכבר הזכרתי זה בסדר האחר (לעיל לא ב). והנה אמר שבאו לפני משה **כל אשר נשאו לבו לקרבה אל המלאכה** , **וכל אשר נדבה רוחו אותו הביאו התרומה** . והנה משה אמר לכולם כי קרא ה' בשם בצלאל ואהליאב (פסוק ל), ואחרי כן קרא להם משה ואל כל חכם לב (להלן לו ב) שיבואו לפניו ונתן להם הנדבה:
@22 (כב~כד) וטעם **ויבואו האנשים על הנשים** . בעבור כי הנדבה בתכשיטין היא מצויה אצל הנשים יותר, וכלן היו להן, ופרקו נזמיהן וטבעותיהן מיד, ובאו תחלה, והאנשים אשר נמצאו להם הביאו עמהם, כי טעם על הנשים שהן היו שם בראשונה והאנשים נטפלו להן. וכן נחה ארם על אפרים (ישעיה ז ב), כי המלחמה ההיא לאפרים, ולא שתם על צאן לבן (בראשית ל ט), ועליו מטה מנשה (במדבר ב כ), והדומים להם. ואמר שבאו כלם אנשים ונשים בחח ונזם וטבעת וכומז ובכל כלי זהב כצמידים ועגילים, כי נמצאו לכלם כלי תכשיט. ואמר כי יש מהם שהניפו תנופת זהב שבור או במטבע:
@22 ואמר **וכל איש אשר נמצא אתו תכלת וארגמן** . כי לא נמצאו מאלה רק למקצתם:
@22 **וחזר** ואמר **אשר נמצא אתו עצי שטים** . כי היו יותר מעטים שבידם עצי שטים:
@22 **ואמר כל מרים תרומת כסף ונחשת** . כי לרוב האנשים היה כסף ונחשת במטבעות וכלים, אבל לא הזכיר זה למעלה (בפסוק כב) עם כלי הזהב, בעבור שהזכיר שם הנשים ואין להם כסף ונחשת רק הזהב בתכשיטין כאשר אמר (לעיל לב ב) נזמי הזהב אשר באזני נשיכם:
@22 **וכל** '' **איש אשר הניף תנופת זהב** . לא היו רבים כמרימי הכסף והנחשת ולא היתה הבאת הזהב מרובה ככסף והנחשת, על כן תקרא זו תנופה וזו תרומה, כי המביא זהב ינופף ידו לחשיבות הנדבה, או הלוקחים יניפו הזהב להראותו, לשבח המביא על נדבתו. ובפרשת אלה פקודי (להלן לח כד, כט) יקרא הזהב גם הנחשת תנופה, כי לא הזכיר שם (בפסוקים כה~כח) תרומה כלל, רק כסף פקודי העדה. ויתכן שיקרא גם הנחשת תנופה, שהיה חשוב להם יותר מן הכסף, מפני שלא היה נמצא בידם ממנו. או שהיה חשוב מאד, כענין שנאמר (עזרא ח כז) וכלי נחשת מצהב טובה שנים חמודות כזהב:
@38 **ויקחו מלפני משה** . הנה ביום אחד הביאו כל הנדבה הזאת (לעיל לה כב~כט) אל אהל מועד שהוא של משה, והחכמים לקחו בו ביום מלפניו ובמחרת בהשכמה, וכן בשני הביאו אליו עוד אל אהלו נדבה והוא צוה להביא אותה אל האומנים, עד שאמרו לו שהם **מרבים להביא והיתה דים והותר** . ולא היה היתרון דבר חשוב שיספר בפרשת אלה פקודי מה עשו בו, אולי היה מונח באהל לחזק בה את בדק המשכן, או לעשות בה כלי שרת כאשר יעשו במקדש במותרות (שקלים פ''ד ה''ד):
@38 **והזכיר** הכתוב (פסוק ה) מרבים העם להביא, לשבח את העם המביאים בנדבתם, ולפאר החכמים בנאמנותם, וגם הנגיד עליהם משובח בזה שהעביר קול במחנה למנעם, כי אין לו חפץ בכספם וזהבם כשאר המושלים בעמם, כענין שאמר לא חמור אחד מהם נשאתי (במדבר טז טו):
@41 **איש ואשה אל יעשו עוד מלאכה** . הממון יקרא מלאכה, וכן אם לא שלח ידו במלאכת רעהו (לעיל כב ז), לרגל המלאכה אשר לפני (בראשית לג יד), וכל המלאכה נמבזה ונמס (ש''א טו ט). והענין, שלא יביאו עוד שום דבר למלאכת הקדש. אבל אמר אל יעשו עוד מלאכה, להכניס הנשים שלא יהיו עוד טוות את העזים. והנה גם ההבאה יקרא מעשה, ומנע מהם הכל:
@43 **ויעשו כל חכם לב בעשי המלאכה את המשכן עשר יריעות** . הנה החזיר בתורה מלאכת המשכן חמש פעמים, כי הזכיר את כולה בצואה בפרט ובכלל. תחלה (לעיל כה י~כח מג) אמר ועשית כך ועשית כך, ואחרי כן (לעיל לא ז~יא) הזכיר כולם בדרך כלל ועשו את כל אשר צויתיך את אהל מועד ואת הארון לעדות, עד ככל אשר צויתיך יעשו:
@43 **והטעם** בזה, שצוה השם למשה שיגיד אל בצלאל ואהליאב ולכל החכמים המלאכה בכללה ואחרי כן יקרבו אליה לעשותה, כי לא יכשרו למלאכת הקדש עד שישמעו כל המלאכה ויבינו אותה ויקבלו עליהם שידעו להשלימה. ובשעת המעשה (לעיל לה יא~כ) הזכיר אותה תחלה בדרך הכלל הנזכר, ואמר (לעיל לא ו~יא) יבואו ויעשו את כל אשר צוה ה' את המשכן את אהלו וגו', ויחסר מכאן פרט אחד, כי בודאי הוצרך משה לאמר אל החכמים העושים המלאכה. עשו המשכן עשר יריעות, ארך היריעה כך ורחב כך, וכן בכל המלאכה, ולא הזכיר הכתוב זה, כי בידוע שאמר להם הכל כסדר, אחרי שעשו כן כל דבר ודבר:
@43 **והטעם** בזה, כי לא הוצרך משה לפרוט להם כל המעשה דבר בדבר כאשר הוזכר בצואה (כה י כח מג) ובמעשה (לו ח לט מב), אבל קצרו להם כאלו אמר שיעשו משכן בעשר יריעות חמש כנגד חמש, והם הבינו כי יעשו לולאות מקבילות וקרסי זהב, וכיוצא בזה בכל המלאכה בקצרה רמז להם הענין, והם הבינו הכל, על כן לא האריך בפרט הזה, ירמוז הכתוב חכמתם ובינתם וטוב השכל שבהם. ואחר כן (בפסוקים לו ח, לט מב) החזיר המלאכה כולה בדרך הפרט הראשון (לעיל כה י~כח מג) ויעש כל חכם לב בעושי המלאכה את המשכן, ויעשו יריעות עזים, ויעש את הקרשים וגו':
@43 **והיה** מספיק בכל הענין (לעיל לה ו~כ) שיאמר ויאמר משה אל כל עדת בני ישראל כל המלאכה אשר צוה ה' אותו, ויאמר (כאן) **ויעשו בני ישראל ככל אשר** :
@43 **צוה ה' את משה כן עשו** , **וירא משה את כל המלאכה והנה עשו אותה כאשר צוה ה' כן עשו אותה ויברך אותם משה** (להלן לט מג). אבל רצה לומר כי משה הזכיר אל כל עדת בני ישראל והחכמים שם (לעיל לה יא~כ) כל המלאכה בכלל, כי נתכוין בזה שיתנדבו העם כדי העבודה למלאכה הגדולה, ובעבור שישמעו החכמים וידעו אם יקבלו לעשותם כאשר נצטוה. ואחר כן הזכיר בפרט המעשה, להגיד שעשו כל החכמים במשכן, זהו שנאמר (כאן) **ויעשו כל חכם לב בעושי המלאכה את המשכן עשר יריעות** :
@43 **ואמר** ויעש יריעות עזים (פסוק יד), ויעש את הקרשים (פסוק כ), ירצה לומר ויעש כל חכם לב יריעות עזים. והזכיר בארון ויעש בצלאל (להלן לז א), להגיד כי האומן הגדול שבהם הוא שעשה לבדו הארון. והטעם, בעבור שהוא מלא רוח אלהים בחכמה בתבונה ובדעת (לעיל לא ג), שיתבונן בו ויעשנו בכוונה רצויה, כי אין במעשהו אומנות גדולה, אבל יש שם מלאכות שצריכות לאומנות יתירה ממנו. וחזר ואמר סתם ויעש את השלחן (להלן לז י), ויעש את המנורה (שם יז):
@43 **ועל** דעת רבי אברהם (שם א) ירמוז אל בצלאל שעשה כל כלי הקדש. ואין כן דעתי, שגם בחצר המשכן אמר כן (להלן לח ט). אבל הוא חוזר לרמוז אל כל חכם לב כאשר אמר (כאן) במשכן:
@43 **ואחר** שהשלים כלל ופרט במעשה, הזכיר ההבאה אל משה בדרך הכלל, ואמר ויביאו את המשכן אל משה את האהל ואת כל כליו וגו' (להלן לט לג), להגיד חכמתם שהביאו אליו הכל כסדר, כי לא הביא אחד מהם מלאכתו לפניו עד שנשלמה כל המלאכה, כאשר אמר (בפסוק שלפניו) ותכל כל עבודת משכן אהל מועד. ואחרי שנשלמה נאספו כלם והראו אותה אליו כסדר, אמרו תחלה, רבינו הנה האוהל והנה כליו, ואחרי כן הנה הארון והנה בדיו, וכן הכל:
@43 **והנה** לא הזכיר במשכן וכל כליו כאשר צוה ה' את משה, אבל באלה הפקודים בבגדי כהונה יזכיר כן בכל דבר ודבר (להלן לט א ה ז כא כו כט לא). והטעם, כי כלל מלאכת המשכן בפסוק שאמר בסוף (להלן לח כב) ובצלאל בן אורי בן חור עשה את כל אשר צוה ה' את משה. ואולי היה זה מפני שנוי הסדר, כמו שהזכירו רבותינו (ברכות נה.). ועל הכלל כל זה דרך חבה ודרך מעלה, לומר כי חפץ השם במלאכה ומזכיר אותה בתורתו פעמים רבות להרבות שכר לעוסקים בה, כענין מה שאמרו במדרש יפה שיחת עבדי אבות לפני הקב''ה מתורתם של בנים, שהרי פרשתו של אליעזר שנים ושלשה דפין היא:
@102 **ויעש את שמן המשחה קדש ואת קטרת הסמים טהור** . לא פירש באלו כאשר פירש באחרים, שעל דרך השאר ראוי שיאמר ויקח בשמים ראש מר דרור וגו' ויעש אותו שמן משחת קדש, ויקח סמים נטף ושחלת וגו', ויעש אותה קטרת רקח מרקחת מעשה רוקח. והטעם, כי בעבור שלא נאמרה בהם הצואה בתשלום המעשה כאשר פירשתי שם (לעיל ל כה, לד), ובקטרת לא הזכיר גם כל הסמים, וסמך עליהם במה שאמר מעשה רוקח, לא הזכיר במעשה כלום, אבל אמר שעשוהו על דעת הרקחים. וזה טעם **קדש טהור מעשה רוקח** :
@110 **במראות הצובאות** . בנות ישראל היו בידן מראות שרואות בהן כשהן מתקשטות ואף אותן לא עכבו, והיה משה מואס בהן מפני שעשויין ליצר הרע, אמר לו הקב''ה אלו חביבין מן הכל שעל ידיהן העמידו הנשים צבאות רבות במצרים וכו', ונעשה הכיור מהם שהוא לשום שלום בין איש לאשתו להשקות מן המים שבו לאשה שקנא לה בעלה ונסתרה. לשון רש''י:
@110 **והטעם** במדרש הזה (תנחומא פקודי י), שבכל מלאכת המשכן קבלו התכשיטין מן הנשים, כדכתיב (לעיל לה כב) ויבואו האנשים על הנשים, והביאו חח ונזם וטבעת וכומז, והכומז כפי מדרשו (במסכת שבת סד.) יותר נמאס, אבל שם נתערבה כל הנדבה, אבל שיעשו כלי מיוחד מן התכשיט העשוי ליצר הרע לא היה משה בוחר בכך עד שנאמר לו כן מפי הגבורה:
@110 **ולא** ידעתי איך יתפרש לפי זה אשר צבאו פתח אהל מועד. ואולי יאמר שהביאו הנשים הנדבה ההיא אל אהל משה שקראו אהל מועד, והוא עצמו קבל מהן על פי הדבור, כי אהל המשכן לא נעשה עדיין:
@110 **ואונקלוס** תרגם דאתיאן לצלאה לתרע משכן זימנא, נוטים דבריו לדברי ר''א שאמר שהיו הנשים האלה עובדות ה', וסרו מתאות זה העולם, ונתנו מראותיהן נדבה, ובאות בכל יום ויום אל פתח אהל מועד להתפלל ולשמוע דברי המצות:
@110 **ויתכן** עוד שנאמר בדרך הפשט שעשה הכיור וכנו ממראות הנשים אשר באו מהן צבא גדול ונאספו אל פתח אהל מועד לתת מראותיהן בנדבת לבן, והיה נחשת המראות נחשת קלל ממורט ויפה מאד, ועל כן ייחד אותו מתחלה לכלי הזה, והנשים בראותן כן נאספות ובאות צבאות צבאות לתת כולן מראותיהן להעשות בהן כל הכיור וכנו. וגם נכון הוא שיתכונו בכך מתחלה מפני ענין הסוטה, והן קבלו כן עליהם בשמחה והתנדבו לתת בו כל מראותיהן:
